import { Schema } from "effect";
export class InvalidRequestError extends Schema.TaggedError()("InvalidRequestError", { message: Schema.String }, { httpApiStatus: 400 }) {
}
export class UnauthorizedError extends Schema.TaggedError()("UnauthorizedError", { message: Schema.String }, { httpApiStatus: 401 }) {
}
export class TunnelNotFoundError extends Schema.TaggedError()("TunnelNotFoundError", { tunnelID: Schema.String, message: Schema.String }, { httpApiStatus: 404 }) {
}
export class CertificateNotFoundError extends Schema.TaggedError()("CertificateNotFoundError", { tunnelID: Schema.String, message: Schema.String }, { httpApiStatus: 404 }) {
}
export class InvalidHostnameError extends Schema.TaggedError()("InvalidHostnameError", { provided: Schema.String, expected: Schema.String, message: Schema.String }, { httpApiStatus: 400 }) {
}
export class HostnameUnavailableError extends Schema.TaggedError()("HostnameUnavailableError", { name: Schema.String, message: Schema.String }, { httpApiStatus: 409 }) {
}
export class CertificateInProgressError extends Schema.TaggedError()("CertificateInProgressError", { tunnelID: Schema.String, message: Schema.String }, { httpApiStatus: 409 }) {
}
export class ServiceUnavailableError extends Schema.TaggedError()("ServiceUnavailableError", { message: Schema.String }, { httpApiStatus: 503 }) {
}
